<template>
 <div ref="stage" class="story-stage sf-ui" :data-scene="state.sceneId" :data-time="state.time.toFixed(3)" role="img" :aria-label="description">
  <div class="story-ambient"></div>
  <div class="story-gym" :style="{transform:geometry.gymTransform,filter:'blur('+geometry.gymBlur+'px)'}"><img :src="assets.gym" alt="A sunlit home gym with a treadmill" fetchpriority="high" /></div>
  <div class="story-world-glass" :style="{opacity:geometry.glassOpacity}"></div>
  <div class="story-copy" :class="{'story-copy--opening':state.time<7,'story-copy--player':state.scene===3}" :style="{opacity:copyOpacity}"><span class="story-eyebrow">{{ state.scene===1?'A WEEK WITH ALEX':String(state.scene).padStart(2,'0')+' / 08 · SUNNYFIT 3.0' }}</span><h1>{{ scene.title }}</h1><p>{{ scene.description }}</p><div class="story-copy-detail" v-if="state.scene>1&&state.scene<8"><span>{{ state.dateLabel }}</span><span>{{ state.scene===3?'30-minute session · time compressed':state.totals.workouts+' workouts · '+state.totals.time+' min' }}</span></div><span v-if="state.scene===1" class="story-scroll-hint">SCROLL TO BEGIN ↓</span></div>
  <div class="story-phone" data-anchor="phone-screen" :style="rect(geometry.phone,{opacity:geometry.phoneOpacity,clipPath:geometry.phoneClip})" aria-hidden="true" inert>
   <div class="story-phone-inner">
    <div class="story-home story-panel" :style="{opacity:state.layers.home}">
     <div class="story-status"><b>9:41</b><img :src="homeAsset('imgRightSide')" alt="" /></div>
     <header class="story-app-header"><span class="story-avatar">A</span><b>Hi, Alex</b><span class="story-header-icons"><img :src="homeAsset('img7')" alt=""/><img :src="homeAsset('imgGroup259')" alt=""/><img :src="homeAsset('imgGroup412')" alt=""/></span></header>
     <img class="story-banner" :src="'/assets/story/trainer-banner.png'" alt="Trainer spotlight" />
     <div class="story-plan-heading"><h2>{{ state.reportReady?'Weekly Report':'Dynamic Plan' }}</h2><span>{{ state.dateLabel }}</span></div>
     <div class="story-recommendation sf-workout-recommendation"><p>{{ homeMessage }}</p><div class="story-cover-space"></div><sf-button>{{ completedRecommendation?'Completed ✓':'Start Now' }}</sf-button><div class="story-quick-actions"><span>↻ Change</span><span>{{ state.recommendation.minutes }} min · {{ state.recommendation.type }}</span></div></div>
     <div class="story-home-data"><b>{{ state.totals.time }} min</b><span>{{ state.reportReady?'Nov 2–8 total':'this week' }} · {{ state.totals.calories }} kcal</span></div>
     <div class="story-calendar"><div v-for="(day,i) in days" :key="i" :class="{'is-selected':i===state.dayIndex%7,'is-done':doneDay(i)}"><span>{{ day }}</span><b>{{ state.dayIndex===7?i+9:i+2 }}</b><small>{{ doneDay(i)?'●':'·' }}</small></div><i :style="{transform:'translateX('+calendarPosition+'px)'}"></i></div>
     <sf-bottom-navigation class="story-app-nav" :items="navigation" active="home"><template #accessory><span class="story-orb-space"></span></template></sf-bottom-navigation>
    </div>
    <div class="story-result story-panel" :style="{opacity:state.layers.result}" data-node-id="581:2863">
     <div class="story-status"><b>9:41</b><img :src="homeAsset('imgRightSide')" alt="" /></div><header class="story-page-title">‹ <b>Workout Data</b> ···</header>
     <div class="story-result-body" :style="{transform:'translateY('+(-110*tween(state.time,25.5,27)*(1-tween(state.time,31.5,33)))+'px)'}">
      <div class="story-result-cover-space"></div><span class="story-small-red">WORKOUT COMPLETE</span><h2>Run complete.</h2><p class="story-muted">Mon, Nov 2, 2026 · Treadmill Run</p>
      <div class="story-result-stats"><sf-card v-for="stat in resultStats" :key="stat.label"><small>{{ stat.label }}</small><strong>{{ stat.value }}</strong></sf-card></div>
      <sf-card class="story-effort" :style="{opacity:tween(state.time,25.5,27)}"><h3>How did that feel?</h3><div class="story-rpe"><span v-for="n in 10" :key="n" :class="{'selected':state.rpe===n}">{{ n }}</span></div><p>{{ state.rpe===null?'Check in with yourself':'7 / 10 · Hard' }}</p></sf-card>
      <sf-insight-card :style="{opacity:tween(state.time,29,30.5)}" :body="scenario.resultInsight" :saved="true" :rpe="7"/>
     </div>
    </div>
    <div class="story-weekly story-panel" :style="{opacity:state.layers.weekly}"><div class="story-status"><b>9:41</b><img :src="homeAsset('imgRightSide')" alt="" /></div><header class="story-page-title">‹ <b>Your Weekly Report</b> ···</header><div class="story-weekly-greeting"><h2>Hi, Alex.</h2><span>Nov 2–8, 2026</span></div><div class="story-weekly-bottom" :style="{opacity:state.insight}"><sf-card><h3>Your workout mix</h3><div v-for="mix in scenario.report.mix" :key="mix.type" class="story-mix"><span>{{ mix.type }}</span><i :style="{width:mix.minutes/30*110+'px'}"></i><b>{{ mix.minutes }} min</b></div></sf-card><sf-insight-card :saved="true" :body="scenario.weeklyInsight"/><sf-button :style="{transform:'scale('+(1+.035*Math.sin(tween(state.time,56,57)*Math.PI))+')'}">Share your week ↗</sf-button></div></div>
    <div class="story-community story-panel" :style="{opacity:state.layers.community}" data-node-id="585:8127"><div class="story-status"><b>9:41</b><img :src="homeAsset('imgRightSide')" alt="" /></div><header class="story-page-title"><b>SunnyFam</b><span>＋</span></header><div class="story-post-author"><span class="story-avatar">A</span><div><b>Alex</b><small>Nov 9, 2026 · {{ state.time<62?'Just now':'2 hours later' }}</small></div></div><p class="story-post-copy">{{ scenario.report.stats.workouts }} workouts last week. One step at a time!</p><div class="story-reactions"><span>♡ {{ state.reactions.likes }} likes</span><span>♧ {{ state.reactions.comments }} comments</span></div><div class="story-comments" :style="{opacity:tween(state.time,62,64)}"><b>SunnyFam</b> Nice work, Alex!<br/><b>Community</b> Love the consistency!</div><small class="story-social-label">Simulated community interaction</small></div>
   </div>
  </div>
  <!-- These anchors stay mounted across scenes. No replace-at-boundary screenshots. -->
  <div class="story-cover" data-anchor="recommendation-cover workout-hero" :style="rect(geometry.cover,{opacity:geometry.coverOpacity,'--cover-text-scale':geometry.coverTextScale})" aria-hidden="true">
   <sf-course-card v-for="(record,i) in scenario.workoutRecords" :key="record.id" :image="posters[i]" :title="record.title" :duration="record.minutes+' min'" :style="{height:'100%',opacity:posterOpacity(i),'--caption-opacity':1-state.layers.player}"/>
   <div class="story-player" :style="{opacity:state.layers.player}"><div class="story-player-top"><span>‹ &nbsp; Treadmill Run</span><span>Connected treadmill</span></div><div class="story-player-metrics"><div><b>{{ clock(state.session.seconds) }}</b><small>TIME ELAPSED</small></div><div><b>{{ state.session.speedMph.toFixed(1) }}</b><small>SPEED (MPH)</small></div><div><b>{{ state.session.calories }}</b><small>CALORIES (KCAL)</small></div><div><b>{{ state.session.distanceMi.toFixed(2) }}</b><small>DISTANCE (MI)</small></div></div><div class="story-player-bottom"><span>{{ state.workoutProgress===1?'Workout complete ✓':'30-minute session · time compressed' }}</span><small>Preview image</small><div><i :style="{width:state.workoutProgress*100+'%'}"></i></div></div></div>
  </div>
  <div class="story-report-anchor" data-anchor="report-card" :style="rect(geometry.report,{opacity:reportOpacity})" aria-hidden="true"><div class="story-report-inner" :style="{width:'343px',transform:'scale(1)'}"><h3>{{ state.time<48?'Your weekly report is ready':'Your Week' }}</h3><p>Nov 2–8 · {{ scenario.report.stats.workouts }} workouts · {{ scenario.report.stats.time }} min</p><svg viewBox="0 0 310 100" class="story-chart"><defs><linearGradient id="story-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#e81d1d" stop-opacity=".32"/><stop offset="1" stop-color="#e81d1d" stop-opacity="0"/></linearGradient></defs><path :d="chartPath+' L298 78 L12 78 Z'" fill="url(#story-chart-fill)"/><path :d="chartPath" stroke="#e81d1d" stroke-width="2" fill="none"/><g v-for="(day,i) in scenario.report.daily" :key="day.date"><circle :cx="12+i*47.6" :cy="78-day.minutes/30*60*chartGrowth" r="3" fill="#e81d1d"/><text :x="12+i*47.6" y="97" text-anchor="middle">{{ day.day }}</text></g></svg><div class="story-report-stats" :style="{opacity:tween(state.time,47.5,49)}"><div v-for="stat in weeklyStats" :key="stat.label"><small>{{ stat.label }}</small><b>{{ stat.value }}</b></div></div><span class="story-report-open" :style="{opacity:1-tween(state.time,47,48)}">Open report →</span></div></div>
  <div class="story-share" data-anchor="share-card" :style="rect(geometry.share,{opacity:state.layers.share})" aria-hidden="true"><canvas ref="shareCanvas" width="720" height="960"></canvas></div>
  <div class="story-orb" data-anchor="orb" :style="rect(geometry.orb,{opacity:geometry.orbOpacity})" aria-hidden="true"><sf-ai-ball ref="orb" :size="56" :external-time="state.time" :external-head="state.orb.head" :state="state.orb.state" fit decorative reduce-motion :style="{'--story-blink':state.orb.blink,transform:'scale('+state.orb.breath+')'}"/></div>
  <div v-for="bubble in bubbles" :key="bubble.id" class="story-reaction-bubble" :style="bubble.style" aria-hidden="true"><span>{{ bubble.icon }}</span>{{ bubble.text }}</div>
  <div v-if="caption" class="story-caption" :style="{opacity:caption.opacity}">{{ caption.text }}</div>
  <div class="story-brand" :style="{opacity:state.layers.brand}"><img src="/assets/story/logo-on-light.svg" alt="SunnyFit"/><span>3.0</span></div>
 </div>
</template>
<script>
import {SfCard,SfButton,SfInsightCard,SfAiBall,SfCourseCard,SfBottomNavigation} from '@/design-system'
import {homeStateAsset} from '@/design-system/assets/home-states'
import {createWeeklyReportCanvas} from '@/views/app/share-weekly-report'
const {scenario}=require('./scenario.cjs')
const {getGeometry,tween,windowAt}=require('./story-state.cjs')
const manifest=require('./scene-manifest.cjs')
const narration=require('./narration.cjs')
const {matrix3d}=require('./projection.cjs')
export default {name:'StoryStage',components:{SfCard,SfButton,SfInsightCard,SfAiBall,SfCourseCard,SfBottomNavigation},props:{state:{type:Object,required:true}},data(){return {width:1440,height:900,scenario,days:['M','T','W','T','F','S','S'],assets:{gym:'/assets/story/home-gym.png',poster:homeStateAsset('ai','img6'),logo:'/assets/story/logo.svg'}}},computed:{
 posters(){return [this.assets.poster,'/assets/movement/real/arm-triceps-stretch.jpg','/assets/figma/v3/plan-completed/imgRectangle1507.png']},
 caption(){const t=this.state.time,cue=narration.find(c=>t>=c.start&&t<c.end);return cue?{text:cue.text,opacity:tween(t,cue.start,cue.start+.3)*(1-tween(t,cue.end-.3,cue.end))}:null},bubbles(){const labels=['Nice work, Alex!','Love the consistency!','Keep going!','You showed up.','One step at a time!','128 moments of encouragement'];return labels.map((text,i)=>{const elapsed=this.state.time-(61+i*.58),p=Math.max(0,Math.min(1,elapsed/2.4)),side=i%2?1:-1,x=this.geometry.mobile?this.width/2+side*70:this.geometry.phone.x+(side<0?-65:this.geometry.phone.w+55);return {id:i,text,icon:i%2?'\u2709':'\u2665',style:{left:x+'px',top:(this.height*.7-p*180)+'px',opacity:Math.sin(p*Math.PI)*this.state.layers.community,transform:'translate(-50%,-50%) scale('+(0.8+.2*Math.sin(p*Math.PI))+')'}}})},geometry(){return getGeometry(this.state.time,this.width,this.height)},scene(){return manifest.scenes[this.state.scene-1]},description(){return `${this.scene.title} ${this.scene.description} ${this.state.dateLabel}. ${this.state.totals.workouts} completed workouts, ${this.state.totals.time} minutes. Simulated marketing scenario.`},
 navigation(){return ['Home','Workout','Challenge','Social'].map((label,i)=>({label,value:label.toLowerCase(),icon:this.homeAsset(['imgFrame','imgFrame1','imgGroup','imgFrame2'][i])}))},
 copyOpacity(){return (1-tween(this.state.time,65,68))*(this.state.time<8?1-tween(this.state.time,5,7):windowAt(this.state.time,this.scene.start+.1,this.scene.start+.8,this.scene.end-1,this.scene.end))},
 completedRecommendation(){return this.state.records.some(r=>r.id===this.state.recommendation.id)},homeMessage(){if(this.state.dayIndex===0)return this.state.time<24?'Ready for your 30-minute run?':'Nice work. Take a moment to recover.';if(this.state.dayIndex<4)return 'Let’s take it easier. How about 20 minutes of mobility?';return 'A little strength, at your own pace.'},
 calendarPosition(){const t=this.state.time;return t>=46?0:[36,38,40,42,44,45].reduce((sum,at)=>sum+tween(t,at,at+.6),0)*44},resultStats(){return [{label:'Time (min)',value:this.clock(scenario.workoutRecords[0].minutes*60)},{label:'Calories (kcal)',value:scenario.workoutRecords[0].calories},{label:'Distance (mi)',value:scenario.workoutRecords[0].distanceMi.toFixed(2)}]},
 weeklyStats(){return [{label:'Workouts',value:scenario.report.stats.workouts},{label:'Active days',value:scenario.report.stats.activeDays},{label:'Time (min)',value:scenario.report.stats.time},{label:'Calories (kcal)',value:scenario.report.stats.calories}]},
 reportOpacity(){return windowAt(this.state.time,46,47,56.5,58)},chartGrowth(){return tween(this.state.time,46,47.2)},chartPath(){return scenario.report.daily.map((d,i)=>(i?'L':'M')+(12+i*47.6)+' '+(78-d.minutes/30*60*this.chartGrowth)).join(' ')}
 },mounted(){this.resize=new ResizeObserver(entries=>{this.width=entries[0].contentRect.width;this.height=entries[0].contentRect.height});this.resize.observe(this.$el);const canvas=createWeeklyReportCanvas({weekStart:scenario.report.period[0],weekEnd:scenario.report.period[1],daily:scenario.report.daily,stats:scenario.report.stats},{footer:'Alex · Simulated marketing scenario'});this.$refs.shareCanvas.getContext('2d').drawImage(canvas,0,0)},beforeDestroy(){this.resize.disconnect()},methods:{tween,homeAsset(name){return homeStateAsset('ai',name)},rect(r,extra={}){return {...extra,left:'0px',top:'0px',width:r.localW+'px',height:r.localH+'px',borderRadius:r.radius+'px',transform:matrix3d(r.matrix),transformOrigin:'0 0'}},clock(seconds){return String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0')},doneDay(i){return this.state.dayIndex!==7&&this.state.records.some(r=>Number(r.date.slice(-2))===i+2)},posterOpacity(i){const t=this.state.time;return i===0?1-tween(t,35.5,36.5):i===1?tween(t,35.5,36.5)*(1-tween(t,41.5,42.5)):tween(t,41.5,42.5)}}}
</script>
<style src="./story.css"></style>
